import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({ standalone: true, selector: 'app-login', imports: [CommonModule, FormsModule, RouterLink], templateUrl: './login.component.html', styles: [`.box{max-width:420px;margin:24px auto}.box .card{padding:16px}`] })
export class LoginComponent { email = ''; password = ''; error = ''; loading = false; constructor(private auth: AuthService, private router: Router) {} submit() { this.error = ''; this.loading = true; this.auth.login(this.email, this.password).subscribe({ next: (res) => { this.auth.saveToken(res.access_token); this.auth.fetchMe().subscribe(u => { this.auth.setUser(u); this.router.navigateByUrl('/'); }); }, error: err => { this.error = err?.error?.detail || 'Login failed'; this.loading = false; } }); } }
<div class="box">
  <div class="card">
    <h2>Login</h2>
    <form (ngSubmit)="submit()">
      <div class="label">Email</div>
      <input class="input" [(ngModel)]="email" name="email" type="email" required />
      <div class="label">Password</div>
      <input class="input" [(ngModel)]="password" name="password" type="password" required />
      <button class="btn" [disabled]="loading" type="submit" style="margin-top:12px">Login</button>
      <p *ngIf="error" style="color:red">{{error}}</p>
    </form>
    <p>New user? <a class="link" routerLink="/register">Register</a></p>
  </div>
</div>
